    private const string GeneratedGraphicsModeSource = """
        // <auto-generated/>
        namespace Generated;

        public readonly struct Hdc { }
        public enum GraphicsMode { Compatible }
        public interface IContext { Hdc Handle { get; } }

        public static class Interop
        {
            /// <summary><para>Gets the graphics mode.</para></summary>
            /// <param name="hdc">The device context handle.</param>
            /// <returns>The graphics mode identifier.</returns>
            public static int GetGraphicsMode(Hdc hdc) => 0;
        }
        """;

    private const string GeneratedComStructSource = """
        // <auto-generated/>
        namespace Generated;

        public readonly struct IFileDialogEvents
        {
            /// <summary>Handles a file dialog confirmation.</summary>
            /// <param name="dialog">The file dialog.</param>
            /// <returns>The result.</returns>
            public int OnFileOk(int dialog) => 0;
        }

        public readonly struct ID2D1RenderTarget
        {
            /// <summary>Draws the text layout.</summary>
            /// <param name="origin">The origin.</param>
            /// <param name="layout">The layout.</param>
            public void DrawTextLayout(int origin, string layout) { }
        }
        """;

    private const string GeneratedDialogEventOverloadsSource = """
        // <auto-generated/>
        namespace Generated;

        public readonly unsafe struct IFileDialogEvents
        {
            /// <summary>Handles an overwrite.</summary>
            /// <param name="response">The response pointer.</param>
            /// <returns>The result.</returns>
            public int OnOverwrite(int* response) => 0;

            /// <inheritdoc cref="OnOverwrite(int*)"/>
            public int OnOverwrite(out int response)
            {
                response = 0;
                return 0;
            }
        }
        """;

    private static CompilationReference CreateGeneratedMetadataAliasReference(MetadataReference reference) =>
        CreateCompilationReference(
            """
            [System.CodeDom.Compiler.GeneratedCode("test", "1.0")]
            public static class GeneratedApi
            {
                /// <inheritdoc cref="External.Get(int)"/>
                public static int Get(int value) => External.Get(value);
            }
            """,
            assemblyName: "GeneratedMetadataAlias",
            additionalReferences: [reference]);

    [TestMethod]
    public async Task AnalyzeMember_CrefToGeneratedMethodWithDifferentParameterAndReturnType_ReportsBoth()
    {
        IReadOnlyList<(string Source, string FileName)> sources =
        [
            (GeneratedGraphicsModeSource, "Interop.g.cs"),
            (
                """
                using Generated;

                public static class ContextExtensions
                {
                    /// <inheritdoc cref="Generated.Interop.GetGraphicsMode(Generated.Hdc)"/>
                    public static GraphicsMode GetGraphicsMode<T>(this T context) where T : IContext =>
                        (GraphicsMode)Interop.GetGraphicsMode(context.Handle);
                }
                """,
                "ContextExtensions.cs")
        ];

        SyntaxTree generatedTree = CSharpSyntaxTree.ParseText(sources[0].Source, path: sources[0].FileName);
        SyntaxTree wrapperTree = CSharpSyntaxTree.ParseText(sources[1].Source, path: sources[1].FileName);
        CSharpCompilation compilation = CSharpCompilation.Create(
            "GraphicsModeCref",
            syntaxTrees: [generatedTree, wrapperTree],
            references: RoslynTestEnvironment.References,
            options: new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
        XmlCrefAttributeSyntax cref = wrapperTree.GetRoot().DescendantNodes(descendIntoTrivia: true)
            .OfType<XmlCrefAttributeSyntax>().Single();
        SymbolInfo target = compilation.GetSemanticModel(wrapperTree).GetSymbolInfo(cref.Cref);
        target.Symbol.Should().BeAssignableTo<IMethodSymbol>();

        ImmutableArray<Diagnostic> diagnostics = await AnalyzeAsync(sources).ConfigureAwait(false);

        diagnostics.Should().HaveCount(2);
        diagnostics.Should().ContainSingle(diagnostic => IsParameterDocumentationDiagnostic(diagnostic));
        diagnostics.Should().ContainSingle(diagnostic => IsReturnDocumentationDiagnostic(diagnostic));
        diagnostics.Should().OnlyContain(diagnostic => diagnostic.Location.GetRequiredSourceTree().FilePath == "ContextExtensions.cs");
    }

