    [TestMethod]
    public async Task AnalyzeMember_CrefThroughGeneratedMethodChain_InheritsMatchingSignatureTags()
    {
        IReadOnlyList<(string Source, string FileName)> sources =
        [
            (
                """
                // <auto-generated/>
                public static class GeneratedApi
                {
                    /// <summary>Transforms the value.</summary>
                    /// <param name="value">The value.</param>
                    /// <returns>The transformed value.</returns>
                    public static int Root(int value) => value;

                    /// <inheritdoc cref="Root(int)"/>
                    public static int Alias(int value) => Root(value);
                }
                """,
                "GeneratedApi.g.cs"),
            (
                """
                public static class Sample
                {
                    /// <inheritdoc cref="GeneratedApi.Alias(int)"/>
                    public static int Get(int value) => GeneratedApi.Alias(value);
                }
                """,
                "Sample.cs")
        ];

        ImmutableArray<Diagnostic> diagnostics = await AnalyzeAsync(sources).ConfigureAwait(false);

        diagnostics.Should().BeEmpty();
    }

